import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Reverter {
    receive() external payable { revert(); }
}

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testRegression_property() public {
        address a = address(0x1234);
        address b = address(reverter);

        vm.deal(a, 1 ether);
        vm.deal(b, 0);

        vm.prank(a);
        c.addToBalance{value: 1 ether}();

