pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a contract that reverts on receive
        Reverter reverter = new Reverter();
        address alice = address(0x1111);
        address bob = address(reverter);

        // Fund Alice with 1 ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Fund Bob (the reverter) with 1 ether
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.addToBalance{value: 1 ether}();

        // Bob attempts to withdraw; his call reverts
        vm.prank(bob);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        assertTrue(!success); // withdrawal reverts

        // In the reference, Bob's balance should still be 1 ether
        uint256 bobBalance = c.getBalance(bob);
        assertTrue(bobBalance == 1 ether);
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
}

